(()=>{'use strict';
const db=window.KS_DB,config=window.KS_CONFIG,$=s=>document.querySelector(s),root=$('#app'),page=document.body.dataset.page;
let currentShopPage=1;const SHOP_PAGE_SIZE=24;
let adminPageNumber=1,adminPageSize=20,adminSearch='',adminView=new URLSearchParams(location.search).get('vista')||'all';
let catalog=[],favIds=[],activeAdminTab=new URLSearchParams(location.search).get('tab')||'dashboard';
const money=n=>n==null||n===''?'Precio pendiente':new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0}).format(Number(n)||0);
const retail=p=>p?.precio_detal??p?.precio??null;
const wholesale=p=>p?.precio_mayor??null;
const wholesaleMinimum=p=>Math.max(2,Number(p?.minimo_mayor)||6);
const parseCOP=value=>{
 const raw=String(value??'').trim();if(!raw)return null;
 const clean=raw.replace(/\$/g,'').replace(/\s/g,'');
 if(/^\d+$/.test(clean))return Number(clean);
 if(/^\d{1,3}(?:[.,]\d{3})+$/.test(clean))return Number(clean.replace(/[.,]/g,''));
 return NaN;
};
const tierPrice=(p,qty=1)=>wholesale(p)!=null&&Number(wholesale(p))>0&&qty>=wholesaleMinimum(p)?Number(wholesale(p)):Number(retail(p)||0);
const tierName=(p,qty=1)=>wholesale(p)!=null&&Number(wholesale(p))>0&&qty>=wholesaleMinimum(p)?'Mayor':'Detal';
const dualPrices=p=>`<div class="dual-prices"><div><span>AL DETAL</span><b>${money(retail(p))}</b></div><div class="wholesale-price"><span>AL MAYOR · ${wholesaleMinimum(p)}+ UDS</span><b>${money(wholesale(p))}</b></div></div>`;
const available=p=>Boolean(p&&p.activo&&Number(p.stock)>0&&retail(p)!=null&&Number(retail(p))>0);
const presentation=p=>p.presentacion_ml?`${Number(p.presentacion_ml)} ml`:'Presentación pendiente';
const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const url=s=>{try{let u=new URL(s,location.href);return ((['https:','http:'].includes(u.protocol))||(u.protocol==='data:'&&/^data:image\/(?:png|jpeg|webp);base64,/i.test(u.href)))?safe(u.href):''}catch{return''}};
const ico=(name,size=20)=>{const p={bag:'<path d="M4 7h16l-1 14H5L4 7Z"/><path d="M9 9V6a3 3 0 0 1 6 0v3"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>',heart:'<path d="M20.8 4.6a5.6 5.6 0 0 0-7.9 0l-.9.9-.9-.9a5.6 5.6 0 0 0-7.9 7.9l8.8 8.8 8.8-8.8a5.6 5.6 0 0 0 0-7.9Z"/>',search:'<circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 5 5"/>',arrow:'<path d="M4 12h16m-7-7 7 7-7 7"/>',menu:'<path d="M4 7h16M4 12h16M4 17h16"/>',x:'<path d="m5 5 14 14M19 5 5 19"/>',check:'<path d="m4 12 5 5L20 6"/>',spark:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5z"/>',shield:'<path d="m12 2 9 4v6c0 5-3.5 8-9 10-5.5-2-9-5-9-10V6z"/><path d="m8 12 3 3 5-6"/>',truck:'<path d="M2 7h12v11H2zM14 11h4l4 4v3h-8z"/><circle cx="6" cy="19" r="2"/><circle cx="18" cy="19" r="2"/>',filter:'<path d="M3 5h18l-7 8v5l-4 2v-7z"/>',plus:'<path d="M12 4v16M4 12h16"/>',minus:'<path d="M4 12h16"/>',trash:'<path d="M4 7h16M10 3h4M7 7l1 14h8l1-14M10 11v6M14 11v6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 3"/>',crown:'<path d="M3 7l5 4 4-7 4 7 5-4-2 12H5z"/>',star:'<path d="m12 2 3 7 8 .7-6 5 2 8-7-4-7 4 2-8-6-5L9 9z"/>',chev:'<path d="m7 10 5 5 5-5"/>',logout:'<path d="M10 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h5M14 7l5 5-5 5M19 12H9"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M19 5l-2 2M7 17l-2 2"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 18v3h16v-3"/>'}[name]||p.spark;return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${p}</svg>`};
const cartGet=()=>{try{return JSON.parse(localStorage.getItem('kingseduccion_cart')||'[]')}catch{return[]}};
const cartSet=v=>{localStorage.setItem('kingseduccion_cart',JSON.stringify(v));updateCounters()};
const cartDetails=()=>cartGet().map(x=>({p:catalog.find(p=>p.id===x.id),cantidad:x.cantidad})).filter(x=>available(x.p));
const cartTotal=()=>cartDetails().reduce((s,x)=>s+tierPrice(x.p,x.cantidad)*x.cantidad,0);
const cartCount=()=>cartGet().reduce((s,x)=>s+x.cantidad,0);
const updateCounters=()=>document.querySelectorAll('[data-cart-count]').forEach(n=>n.textContent=cartCount());
function toast(message,type='success'){let t=$('#toast');if(!t){t=document.createElement('div');t.id='toast';t.className='toast';t.setAttribute('role','status');document.body.append(t)}t.className=`toast show ${type}`;t.innerHTML=`${ico(type==='error'?'x':'check',16)} <span>${safe(message)}</span>`;clearTimeout(window.__kingToast);window.__kingToast=setTimeout(()=>t.classList.remove('show'),4000)}
function visual(p,i=0,large=false){const image=p.imagen_url&&url(p.imagen_url);return `<div class="bottle-stage tone-${(i%6)+1}${large?' stage-large':''}">${image?`<img class="bottle-photo" loading="lazy" alt="${safe(p.nombre)}" src="${image}">`:`<div class="bottle-art"><div class="bottle-cap"></div><div class="bottle-neck"></div><div class="bottle-body"><div class="bottle-shine"></div><div class="bottle-label"><span>KINGSEDUCCION</span><b>${safe(p.nombre.split(' ').slice(0,2).join(' '))}</b><small>${safe(p.concentracion==='Sin especificar'?'FRAGRANCE':(p.concentracion||'FRAGRANCE'))}</small></div></div></div>`}<div class="stage-glow"></div></div>`}
function card(p,i=0){const fav=favIds.includes(p.id);return `<article class="product-card reveal"><a href="producto.html?id=${encodeURIComponent(p.id)}" class="product-image" aria-label="Ver ${safe(p.nombre)}">${visual(p,i)}${p.destacado?'<span class="product-tag">Selección</span>':''}</a><button class="favorite-pill ${fav?'is-active':''}" data-action="fav" data-id="${safe(p.id)}" aria-label="${fav?'Quitar de favoritos':'Añadir a favoritos'}">${ico('heart',18)}</button><div class="product-info"><div class="product-micro">${safe(p.marca==='Sin especificar'?'Referencia '+p.sku:p.marca)}${p.genero==='Sin especificar'?'':' · '+safe(p.genero)}</div><h3><a href="producto.html?id=${encodeURIComponent(p.id)}">${safe(p.nombre)}</a></h3><div class="product-meta">${safe(p.familia)} <span>· ${safe(presentation(p))}</span></div><div class="product-bottom"><div class="card-prices"><small>Detal</small><strong>${money(retail(p))}</strong>${wholesale(p)!=null?`<small class="mayor-caption">Mayor ${money(wholesale(p))} / ${wholesaleMinimum(p)}+ uds.</small>`:''}</div><button class="round-add" data-action="add" data-id="${safe(p.id)}" aria-label="Agregar ${safe(p.nombre)} al carrito" ${!available(p)?'disabled title="Pendiente de precio o stock"':''}>${ico('plus',20)}</button></div></div></article>`}
function head(title,eyebrow='KINGSEDUCCION',desc=''){return `<section class="inner-hero"><div class="container"><p class="eyebrow"><span class="mini-line"></span>${safe(eyebrow)}</p><h1>${title}</h1>${desc?`<p class="lead">${safe(desc)}</p>`:''}</div></section>`}
function header(){const u=db.profile,admin=u?.rol==='ADMIN';return `<div class="announcement">KINGSEDUCCION PRIVÉ <span>✦</span> PRECIOS AL DETAL Y AL MAYOR · COLOMBIA</div><header class="site-header"><div class="container nav-wrap"><a class="brand" href="index.html"><span class="brand-symbol">K<span>✦</span></span><span class="brand-label"><b>KINGSEDUCCION</b><small>THE ART OF FRAGRANCE</small></span></a><nav class="nav-links" id="main-nav" aria-label="Menú principal"><a href="index.html" ${page==='inicio'?'class="current"':''}>Inicio</a><a href="tienda.html" ${['tienda','producto'].includes(page)?'class="current"':''}>Colección</a><a href="test.html" ${page==='test'?'class="current"':''}>Tu fragancia</a><a href="nosotros.html" ${page==='nosotros'?'class="current"':''}>Nosotros</a>${admin?'<a href="admin.html" class="admin-link">Administración</a>':''}</nav><div class="nav-actions"><a class="icon-btn" href="favoritos.html" aria-label="Mis favoritos">${ico('heart',20)}</a><a class="icon-btn" href="${u?'cuenta.html':'login.html'}" aria-label="Mi cuenta">${ico('user',20)}</a><a class="icon-btn cart-icon" href="carrito.html" aria-label="Mi carrito">${ico('bag',20)}<span class="cart-badge" data-cart-count>${cartCount()}</span></a><button class="icon-btn hamburger" id="nav-toggle" aria-label="Abrir menú" aria-expanded="false">${ico('menu',24)}</button></div></div></header>${!db.LIVE?'<div class="demo-banner">MODO DEMOSTRACIÓN — Los productos y pedidos son datos de prueba guardados en este navegador. <a href="admin.html">Ver panel de prueba</a></div>':''}`}
function footer(){return `<footer class="footer"><div class="container"><div class="footer-grid"><div><a class="brand footer-brand" href="index.html"><span class="brand-symbol">K<span>✦</span></span><span class="brand-label"><b>KINGSEDUCCION</b><small>THE ART OF FRAGRANCE</small></span></a><p>Fragancias que cuentan historias. Elegancia, personalidad y descubrimiento en cada esencia.</p><div class="social-note">HECHO PARA QUIENES DEJAN HUELLA.</div></div><div><h4>Explorar</h4><a href="tienda.html">Colección</a><a href="test.html">Test de fragancias</a><a href="nosotros.html">Nuestra esencia</a></div><div><h4>Tu cuenta</h4><a href="login.html">Iniciar sesión</a><a href="cuenta.html">Club KingSeduccion</a><a href="pedidos.html">Mis pedidos</a><a href="favoritos.html">Favoritos</a></div><div><h4>Contáctanos</h4><p>${safe(config.STORE_CITY)}</p><p>Pedidos y entregas a coordinar con la tienda.</p>${config.WHATSAPP_NUMBER?`<a href="https://wa.me/${safe(config.WHATSAPP_NUMBER)}" target="_blank" rel="noopener">Escríbenos por WhatsApp ${ico('arrow',15)}</a>`:''}</div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} KINGSEDUCCION. Todos los derechos reservados.</span><span>PERFUMERÍA · ESTILO · IDENTIDAD</span></div></div></footer>`}
async function home(){const featured=catalog.filter(p=>p.activo&&p.destacado).slice(0,4);if(!featured.length)featured.push(...catalog.filter(p=>p.activo).slice(0,4));return `<section class="hero"><div class="hero-text"><div class="hero-content"><p class="eyebrow"><span class="mini-line"></span> UNA NUEVA FORMA DE ELEGIR</p><h1>Tu esencia.<br>Tu <em>distinción.</em></h1><p>Una colección extraordinaria para quienes saben que un aroma puede decirlo todo, sin pronunciar una palabra.</p><div class="hero-buttons"><a href="tienda.html" class="btn btn-gold">Explorar colección ${ico('arrow',18)}</a><a href="test.html" class="text-link">Descubre tu esencia ${ico('arrow',17)}</a></div><div class="hero-stats"><div><strong>01</strong><span>Tu estilo</span></div><div><strong>02</strong><span>Tu esencia</span></div><div><strong>03</strong><span>Tu historia</span></div></div></div></div><div class="hero-art"><div class="hero-orbit orbit-one"></div><div class="hero-orbit orbit-two"></div><span class="hero-vertical">KINGSEDUCCION — PRIVATE COLLECTION</span><div class="hero-bottle">${visual(featured[0]||{nombre:'KINGSEDUCCION',concentracion:'PARFUM',imagen_url:''},0,true)}</div><div class="hero-caption"><span>COLLECTION N° 01</span><strong>La elegancia<br>se lleva puesta.</strong></div></div></section>
<section class="benefits"><div class="container benefits-grid"><div>${ico('shield',24)}<span><b>Compra con confianza</b><small>Tu pedido, siempre bajo control</small></span></div><div>${ico('truck',24)}<span><b>Envíos coordinados</b><small>Consulta cobertura y condiciones</small></span></div><div>${ico('spark',24)}<span><b>Tu aroma ideal</b><small>Descúbrelo con nuestro test</small></span></div></div></section>
<section class="section section-products"><div class="container"><div class="section-top"><div><p class="eyebrow">UNA SELECCIÓN ESPECIAL</p><h2>Esencias para <em>recordar.</em></h2></div><a class="text-link dark-link" href="tienda.html">Ver colección completa ${ico('arrow',18)}</a></div>${featured.length?`<div class="products-grid">${featured.map(card).join('')}</div>`:'<div class="empty">Próximamente encontrarás nuestros perfumes destacados.</div>'}</div></section>
<section class="discovery"><div class="container discovery-grid"><div class="discovery-art"><span class="discovery-ring ring-a"></span><span class="discovery-ring ring-b"></span><div class="discovery-flower">✳</div><small>PERSONALIZED FRAGRANCE FINDER</small></div><div class="discovery-text"><p class="eyebrow">UN VIAJE A TU ESENCIA</p><h2>No es solo un perfume.<br><em>Es quien eres.</em></h2><p>Responde unas preguntas sobre tus gustos, el clima y tus momentos favoritos. Te mostraremos fragancias del catálogo que podrían acompañarte.</p><div class="discovery-steps"><span>01. TUS GUSTOS</span><span>02. TU MOMENTO</span><span>03. TU FRAGANCIA</span></div><a class="btn btn-gold" href="test.html">Hacer mi test ${ico('arrow',18)}</a></div></div></section>
<section class="section club"><div class="container club-grid"><div><p class="eyebrow">CLUB KINGSEDUCCION</p><h2>Tu pasión merece <em>recompensas.</em></h2><p>Con una cuenta puedes guardar favoritos, consultar tus pedidos y acumular 1 punto por cada $1.000 COP de compras marcadas como pagadas.</p><a class="btn btn-outline-dark" href="${db.user?'cuenta.html':'registro.html'}">${db.user?'Ver mi club':'Unirme al club'} ${ico('arrow',18)}</a></div><div class="club-art"><span>THE</span><strong>K</strong><em>CLUB</em><div class="club-seal">✦ MEMBERS ONLY ✦</div></div></div></section>
<section class="quote-band"><div class="container"><p>“Un perfume es el detalle invisible que se vuelve inolvidable.”</p><span>KINGSEDUCCION · THE ART OF FRAGRANCE</span></div></section>`}
function filterProducts(reset=false){
 if(reset)currentShopPage=1;
 let q=($('#filter-search')?.value||'').trim().toLocaleLowerCase(),family=$('#filter-family')?.value||'',gender=$('#filter-gender')?.value||'',sort=$('#filter-sort')?.value||'default';
 let items=catalog.filter(p=>p.activo&&(p.nombre+' '+p.marca+' '+p.notas+' '+p.sku).toLocaleLowerCase().includes(q)&&(!family||p.familia===family)&&(!gender||p.genero===gender));
 if(sort==='asc')items.sort((a,b)=>(retail(a)==null?Infinity:Number(retail(a)))-(retail(b)==null?Infinity:Number(retail(b))));
 if(sort==='desc')items.sort((a,b)=>(retail(b)==null?-Infinity:Number(retail(b)))-(retail(a)==null?-Infinity:Number(retail(a))));
 if(sort==='name')items.sort((a,b)=>a.nombre.localeCompare(b.nombre));
 let pages=Math.ceil(items.length/SHOP_PAGE_SIZE);currentShopPage=Math.max(1,Math.min(currentShopPage,pages||1));
 let portion=items.slice((currentShopPage-1)*SHOP_PAGE_SIZE,currentShopPage*SHOP_PAGE_SIZE);
 $('#catalog-products').innerHTML=portion.length?portion.map(card).join(''):'<div class="empty wide">No se encontraron fragancias con esos filtros. Prueba con otros criterios.</div>';
 $('#result-count').textContent=`${items.length} referencias · Página ${currentShopPage} de ${pages||1}`;
 const paging=$('#shop-pagination');if(paging)paging.innerHTML=pages>1?`<nav class="catalog-paging" aria-label="Páginas de catálogo"><button type="button" data-action="shop-page" data-page="${currentShopPage-1}" ${currentShopPage===1?'disabled':''}>Anterior</button><span>Página ${currentShopPage} de ${pages}</span><button type="button" data-action="shop-page" data-page="${currentShopPage+1}" ${currentShopPage===pages?'disabled':''}>Siguiente</button></nav>`:'';
}

async function shop(){return `${head('Encuentra tu <em>esencia.</em>','THE COLLECTION','Cada fragancia es una historia que comienza contigo.')}<section class="section shop"><div class="container"><div class="shop-bar"><label class="search-field">${ico('search',20)}<input id="filter-search" placeholder="Busca por nombre, marca o notas..." aria-label="Buscar fragancias"></label><label class="select-field"><span>Tipo / familia</span><select id="filter-family"><option value="">Todas</option>${[...new Set([...window.KING_FAMILIES,...catalog.map(p=>p.familia)])].map(f=>`<option value="${safe(f)}">${safe(f)}</option>`).join('')}</select></label><label class="select-field"><span>Género</span><select id="filter-gender"><option value="">Todos</option><option>Hombre</option><option>Mujer</option><option>Unisex</option></select></label><label class="select-field"><span>Ordenar</span><select id="filter-sort"><option value="default">Destacados</option><option value="asc">Menor precio</option><option value="desc">Mayor precio</option><option value="name">Nombre A–Z</option></select></label></div><div class="shop-results"><span id="result-count">${catalog.length} referencias</span><span>ELIGE TU PRÓXIMA FIRMA AROMÁTICA</span></div><div class="products-grid" id="catalog-products">${catalog.filter(p=>p.activo).slice(0,SHOP_PAGE_SIZE).map(card).join('')}</div><div id="shop-pagination"></div></div></section>`}
async function detail(){let id=new URLSearchParams(location.search).get('id'),p=catalog.find(x=>x.id===id&&x.activo);if(!p)return `${head('Fragancia no encontrada')}<div class="container section empty">El perfume no está disponible. <a href="tienda.html">Volver al catálogo</a></div>`;let rec=catalog.filter(x=>x.id!==p.id&&x.activo&&x.familia===p.familia).slice(0,4);return `<div class="container breadcrumb"><a href="tienda.html">Colección</a> / <span>${safe(p.nombre)}</span></div><section class="container detail-grid"><div class="detail-art">${visual(p,catalog.indexOf(p),true)}</div><div class="detail-copy"><p class="eyebrow">${safe(p.marca==='Sin especificar'?'Referencia '+p.sku:p.marca)}${p.genero==='Sin especificar'?'':' · '+safe(p.genero)}</p><h1>${safe(p.nombre)}</h1><p class="detail-family">${safe(p.familia)}${p.concentracion==='Sin especificar'?'':' · '+safe(p.concentracion)}</p><div class="detail-line"></div>${dualPrices(p)}<p>${safe(p.descripcion||p.contenido_catalogo||'Referencia del catálogo. Descripción pendiente de completar.')}${p.pagina_catalogo?` · Catálogo: página ${p.pagina_catalogo}, ${safe(p.ubicacion_catalogo||'')}`:''}</p><div class="product-specs"><div><span>Presentación</span><strong>${safe(presentation(p))}</strong></div><div><span>Familia</span><strong>${safe(p.familia)}</strong></div><div><span>Notas</span><strong>${safe(p.notas||'Pendientes de confirmar')}</strong></div><div><span>Disponibilidad</span><strong class="${p.stock<=5?'low-stock':''}">${p.stock>0?`${p.stock} unidades`:'Sin existencias registradas'}</strong></div></div><div class="detail-actions"><button class="btn btn-gold" data-action="add" data-id="${safe(p.id)}" ${!available(p)?'disabled title="Pendiente de precio o stock"':''}>${ico('bag',19)} Agregar al carrito</button><button class="btn btn-outline-dark" data-action="fav" data-id="${safe(p.id)}">${ico('heart',18)} ${favIds.includes(p.id)?'Guardado':'Guardar'}</button></div><p class="small-muted">Precio mayorista automático desde el mínimo indicado por perfume. El pago y la entrega se coordinan después de confirmar tu pedido.</p></div></section>${rec.length?`<section class="section detail-more"><div class="container"><div class="section-top"><div><p class="eyebrow">TAMBIÉN TE PUEDE GUSTAR</p><h2>Descubre algo <em>nuevo.</em></h2></div></div><div class="products-grid">${rec.map(card).join('')}</div></div></section>`:''}`}
async function cart(){const rows=cartDetails();return `${head('Tu selección.','TU CARRITO','Cada fragancia que eliges cuenta una parte de tu historia.')}<section class="section"><div class="container">${rows.length?`<div class="cart-layout"><div class="cart-list">${rows.map(({p,cantidad})=>`<article class="cart-row"><a class="cart-thumb" href="producto.html?id=${encodeURIComponent(p.id)}">${visual(p,catalog.indexOf(p))}</a><div class="cart-data"><span>${safe(p.marca)}</span><h3>${safe(p.nombre)}</h3><small>${safe(presentation(p))} · ${safe(p.concentracion)}</small><strong>${money(tierPrice(p,cantidad))} / unidad · ${tierName(p,cantidad)}</strong><small>${wholesale(p)!=null?`Mayor desde ${wholesaleMinimum(p)} unidades`:"Precio al detal"}</small></div><div class="qty-wrap"><button data-action="qty" data-id="${safe(p.id)}" data-step="-1" aria-label="Restar unidad">${ico('minus',15)}</button><b>${cantidad}</b><button data-action="qty" data-id="${safe(p.id)}" data-step="1" aria-label="Sumar unidad">${ico('plus',15)}</button></div><button class="icon-btn remove-btn" data-action="remove" data-id="${safe(p.id)}" aria-label="Quitar producto">${ico('trash',19)}</button></article>`).join('')}</div><aside class="summary-card"><h3>Tu pedido · detal y mayor</h3><div class="summary-row"><span>Productos (${cartCount()})</span><strong>${money(cartTotal())}</strong></div><div class="summary-row"><span>Envío</span><strong>Por coordinar</strong></div><div class="summary-total"><span>Subtotal</span><strong>${money(cartTotal())}</strong></div><p>La tienda te confirmará pago, envío y disponibilidad antes de finalizar el proceso.</p><a class="btn btn-gold full" href="checkout.html">Continuar con mi pedido ${ico('arrow',18)}</a><a href="tienda.html" class="text-link dark-link center-link">Seguir explorando</a></aside></div>`:`<div class="empty-state">${ico('bag',54)}<h2>Tu carrito espera una gran fragancia.</h2><p>Explora nuestra colección y encuentra tu próxima favorita.</p><a class="btn btn-gold" href="tienda.html">Explorar colección ${ico('arrow',17)}</a></div>`}</div></section>`}
async function checkout(){const items=cartDetails();return `${head('Finalizar pedido.','CHECKOUT','Confirma tus datos para registrar el pedido. No hay cobros en línea.')}<section class="section"><div class="container">${!items.length?'<div class="empty">Tu carrito está vacío. <a href="tienda.html">Ir al catálogo</a></div>':!db.user?`<div class="auth-needed"><h2>Primero, inicia sesión.</h2><p>Para que puedas consultar el historial y tus puntos, los pedidos se vinculan con tu cuenta.</p><a class="btn btn-gold" href="login.html?next=checkout.html">Iniciar sesión ${ico('arrow',18)}</a></div>`:`<div class="checkout-grid"><form id="checkout-form" class="form-card"><h2>Datos de entrega</h2><div class="field-grid"><label>Nombre completo<input name="nombre" value="${safe(db.profile?.nombre||'')}" maxlength="100" required></label><label>Teléfono / WhatsApp<input name="telefono" type="tel" placeholder="300 123 4567" maxlength="30" required></label><label>Ciudad<input name="ciudad" value="${safe(config.STORE_CITY==='Colombia'?'':config.STORE_CITY)}" maxlength="80" required></label><label>Dirección o punto de entrega<input name="direccion" placeholder="Dirección completa" maxlength="200" required></label></div><label>Comentarios para la tienda (opcional)<textarea name="nota" maxlength="500" rows="4" placeholder="Barrio, referencia o indicaciones adicionales"></textarea></label><label class="checkbox-label"><input type="checkbox" name="confirm" required> Entiendo que el pedido está sujeto a confirmación de pago, disponibilidad y entrega.</label><button class="btn btn-gold full" type="submit">Confirmar pedido ${ico('arrow',17)}</button></form><div class="summary-card"><h3>Tu selección y tarifas</h3>${items.map(x=>`<div class="checkout-item"><span>${x.cantidad} × ${safe(x.p.nombre)}</span><strong>${money(tierPrice(x.p,x.cantidad)*x.cantidad)} <small>(${tierName(x.p,x.cantidad)})</small></strong></div>`).join('')}<div class="summary-total"><span>Total de productos</span><strong>${money(cartTotal())}</strong></div><small>Envío y forma de pago: a coordinar. Los precios y el inventario se validan al registrar el pedido.</small></div></div>`}</div></section>`}
function test(){return `${head('Encuentra tu <em>fragancia.</em>','FRAGRANCE FINDER','Tu próxima esencia podría estar a unas preguntas de distancia.')}<section class="section"><div class="container quiz-grid"><div class="quiz-intro"><p class="eyebrow">KINGSEDUCCION PERSONALIZED</p><h2>Tu aroma.<br><em>Tu identidad.</em></h2><p>Combinamos tus preferencias con las características declaradas del catálogo. Las coincidencias son orientativas: la percepción de un perfume varía de una persona a otra.</p><div class="quiz-index"><span>01</span><span>02</span><span>03</span><span>04</span><span>05</span></div></div><form id="quiz-form" class="form-card quiz-form"><div class="eyebrow">PASO 01 / PERSONALIZA TU BÚSQUEDA</div><div class="field-grid"><label>Presupuesto<select name="presupuesto"><option value="0">Sin límite</option><option value="200000">Hasta $200.000</option><option value="300000">Hasta $300.000</option><option value="400000">Hasta $400.000</option></select></label><label>Familia olfativa<select name="familia"><option value="">Cualquiera</option>${[...new Set([...window.KING_FAMILIES,...catalog.map(p=>p.familia)])].map(f=>`<option value="${safe(f)}">${safe(f)}</option>`).join('')}</select></label><label>Ocasión<select name="ocasion"><option value="">Cualquier ocasión</option><option>Diario</option><option>Trabajo</option><option>Noche / Evento</option></select></label><label>Clima<select name="clima"><option value="">Cualquier clima</option><option value="CALIDO">Cálido</option><option value="FRIO">Frío</option></select></label><label>Preferencia de género<select name="genero"><option value="">Todas</option><option>Hombre</option><option>Mujer</option><option>Unisex</option></select></label><label>Preferencia de intensidad<select name="intensidad"><option value="">Sin preferencia</option><option value="Eau de Toilette">Ligera / fresca</option><option value="Eau de Parfum">Intermedia</option><option value="Parfum">Intensa</option></select></label></div><button class="btn btn-gold full" type="submit">Ver mis recomendaciones ${ico('spark',18)}</button></form></div><div class="container" id="quiz-results"></div></section>`}
function quizResults(fd){let values=Object.fromEntries(fd.entries());const max=Number(values.presupuesto)||Infinity;let result=catalog.filter(p=>p.activo&&available(p)&&retail(p)<=max).map(p=>{let score=40,reasons=[];if(values.familia&&values.familia===p.familia){score+=22;reasons.push('Familia olfativa compatible')}if(values.ocasion&&values.ocasion===p.ocasion){score+=13;reasons.push('Ideal para tu ocasión')}if(values.clima&&(values.clima===p.clima||p.clima==='TODOS')){score+=13;reasons.push('Acorde con el clima elegido')}if(values.genero&&(p.genero===values.genero||p.genero==='Unisex')){score+=7;reasons.push('Coincide con tu preferencia')}if(values.intensidad===p.concentracion){score+=5;reasons.push('Intensidad preferida')}return{p,score,reasons}}).sort((a,b)=>b.score-a.score).slice(0,6);let el=$('#quiz-results');el.innerHTML=`<div class="section-top quiz-result-title"><div><p class="eyebrow">TU SELECCIÓN PERSONALIZADA</p><h2>Estas podrían ser <em>para ti.</em></h2></div><a href="tienda.html" class="text-link dark-link">Ver el catálogo completo ${ico('arrow',17)}</a></div>${result.length?`<div class="products-grid">${result.map(({p,score,reasons},i)=>`<div class="quiz-result"><div class="match-score">${Math.min(99,score)}% · COINCIDENCIA ORIENTATIVA</div>${card(p,i)}<p>${safe(reasons.join(' · ')||'Una opción para descubrir')}</p></div>`).join('')}</div>`:'<div class="empty">El inventario todavía no tiene fragancias con precio y existencias confirmadas. Puedes explorar el catálogo mientras se completa.</div>'}`;el.scrollIntoView({behavior:'smooth',block:'start'})}
async function favoritePage(){const items=catalog.filter(p=>p.activo&&favIds.includes(p.id));return `${head('Tus favoritos.','GUARDADOS PARA TI','Las fragancias que merecen una segunda mirada.')}<section class="section"><div class="container">${items.length?`<div class="products-grid">${items.map(card).join('')}</div>`:`<div class="empty-state">${ico('heart',54)}<h2>Tus favoritos están por descubrir.</h2><p>Guarda los perfumes que te gusten desde la tienda.</p><a href="tienda.html" class="btn btn-gold">Ir a la colección</a></div>`}</div></section>`}
function loginPage(kind){if(db.user&&kind!=='recuperar')return `${head('Ya tienes una sesión iniciada')}<div class="container section center"><a href="cuenta.html" class="btn btn-gold">Ir a mi cuenta</a></div>`;const common=`<div class="auth-art"><span>✦</span><h2>Tu historia<br>tiene <em>un aroma.</em></h2><p>Descubre, guarda y comparte tu universo de fragancias.</p></div>`;
 if(kind==='login')return `<section class="auth-layout">${common}<div class="auth-box"><p class="eyebrow">BIENVENIDO DE NUEVO</p><h1>Iniciar <em>sesión.</em></h1><p>Accede a tu cuenta KingSeduccion.</p><form id="login-form"><label>Correo electrónico<input name="email" type="email" autocomplete="email" required></label><label>Contraseña<input name="password" type="password" autocomplete="current-password" required></label><button class="btn btn-gold full">Iniciar sesión ${ico('arrow',18)}</button></form><p class="auth-link"><a href="recuperar.html">¿Olvidaste tu contraseña?</a></p><p class="auth-link">¿No tienes cuenta? <a href="registro.html">Regístrate aquí</a></p>${demoButtons()}</div></section>`;
 if(kind==='registro')return `<section class="auth-layout">${common}<div class="auth-box"><p class="eyebrow">ÚNETE AL CLUB</p><h1>Crear <em>cuenta.</em></h1><p>Regístrate para guardar favoritos y consultar tus pedidos.</p><form id="register-form"><label>Nombre completo<input name="nombre" required maxlength="100" autocomplete="name"></label><label>Correo electrónico<input name="email" type="email" required autocomplete="email"></label><label>Contraseña (mínimo 8 caracteres)<input name="password" type="password" minlength="8" required autocomplete="new-password"></label><button class="btn btn-gold full">Crear mi cuenta ${ico('arrow',18)}</button></form><p class="auth-link">¿Ya tienes cuenta? <a href="login.html">Inicia sesión</a></p>${demoButtons()}</div></section>`;
 return `<section class="auth-layout">${common}<div class="auth-box"><p class="eyebrow">ACCESO A TU CUENTA</p><h1>Recuperar <em>acceso.</em></h1><p>Te enviaremos un enlace para actualizar tu contraseña.</p><form id="reset-form"><label>Tu correo<input name="email" type="email" required></label><button class="btn btn-gold full">Enviar enlace ${ico('arrow',18)}</button></form><div class="divider-form">Si abriste un enlace de recuperación</div><form id="password-form"><label>Nueva contraseña<input name="password" type="password" minlength="8" required></label><button class="btn btn-outline-dark full">Guardar nueva contraseña</button></form></div></section>`}
function demoButtons(){return db.LIVE?'':`<div class="demo-login"><p>ACCESOS DE DEMOSTRACIÓN (SIN CONTRASEÑA REAL)</p><button data-action="demo-login" data-role="CLIENTE">Probar como cliente</button><button data-action="demo-login" data-role="ADMIN">Probar como administrador</button></div>`}
const tierOf=pts=>[...window.KING_CLUB_TIERS].reverse().find(t=>pts>=t.desde)||window.KING_CLUB_TIERS[0];
async function account(){if(!db.user)return `${head('Tu espacio personal')}<div class="container section auth-needed"><h2>Inicia sesión para continuar</h2><a class="btn btn-gold" href="login.html?next=cuenta.html">Entrar a mi cuenta</a></div>`;let my=await db.getOrders(false);let profile=db.profile||{},pts=Number(profile.puntos)||0,tier=tierOf(pts),next=window.KING_CLUB_TIERS.find(t=>t.desde>pts);return `${head(`Hola, <em>${safe((profile.nombre||db.user.email||'Cliente').split(' ')[0])}.</em>`,'TU ESPACIO KINGSEDUCCION','Tu colección, tus pedidos y tus recompensas, en un solo lugar.')}<section class="section account"><div class="container"><div class="account-tiles"><div class="account-tile crown-tile">${ico('crown',26)}<small>TU NIVEL</small><h3>${tier.nombre}</h3><p>${next?`${next.desde-pts} puntos para ${next.nombre}`:'Has alcanzado el nivel más alto'}</p></div><div class="account-tile">${ico('star',25)}<small>PUNTOS ACUMULADOS</small><h3>${pts.toLocaleString('es-CO')}</h3><p>1 punto por cada $1.000 COP pagados</p></div><div class="account-tile">${ico('bag',25)}<small>MIS PEDIDOS</small><h3>${my.length}</h3><p>Consulta su estado y detalles</p></div><div class="account-tile">${ico('heart',25)}<small>FAVORITOS</small><h3>${favIds.length}</h3><p>Tus aromas guardados</p></div></div><div class="account-bottom"><div class="form-card"><h2>Mi perfil</h2><p><b>Nombre:</b> ${safe(profile.nombre)}</p><p><b>Correo:</b> ${safe(profile.email||db.user.email)}</p><p><b>Rol:</b> ${safe(profile.rol)}</p><button class="btn btn-outline-dark" data-action="logout">${ico('logout',16)} Cerrar sesión</button></div><div class="form-card"><h2>Mis accesos</h2><a class="account-link" href="pedidos.html">Historial de pedidos ${ico('arrow',18)}</a><a class="account-link" href="favoritos.html">Mis favoritos ${ico('arrow',18)}</a><a class="account-link" href="test.html">Mi test de fragancias ${ico('arrow',18)}</a>${profile.rol==='ADMIN'?`<a class="account-link" href="admin.html">Panel de administración ${ico('arrow',18)}</a>`:''}</div></div></div></section>`}
function stateLabel(s){return({nuevo:'Pendiente de pago',pagado:'Pago confirmado',entregado:'Entregado',cancelado:'Cancelado'})[s]||s}
function orderBadge(s){return `<span class="status status-${safe(s)}">${safe(stateLabel(s))}</span>`}
function orderWhatsapp(o){const tel=(config.WHATSAPP_NUMBER||'').replace(/[^0-9]/g,'');if(!tel)return '';let msg=`Hola, quiero coordinar el pedido KingSeduccion ${o.codigo} por ${money(o.total)}. Gracias.`;return `https://wa.me/${tel}?text=${encodeURIComponent(msg)}`}
async function orders(){if(!db.user)return `${head('Mis pedidos')}<div class="container section auth-needed"><p>Inicia sesión para consultar tus pedidos.</p><a class="btn btn-gold" href="login.html?next=pedidos.html">Iniciar sesión</a></div>`;let a=await db.getOrders(false);return `${head('Tus pedidos.','HISTORIAL','Sigue el estado de cada pedido y conserva sus detalles.')}<section class="section"><div class="container">${a.length?`<div class="order-list">${a.map(o=>`<article class="order-row"><div><span class="eyebrow">${safe(o.codigo)}</span><h3>${money(o.total)}</h3><small>${date(o.created_at)} · ${o.order_items?.length||0} productos</small></div><div>${orderBadge(o.estado)}</div><a class="btn btn-outline-dark" href="pedido.html?codigo=${encodeURIComponent(o.codigo)}">Ver detalle ${ico('arrow',17)}</a></article>`).join('')}</div>`:'<div class="empty-state"><h2>Aún no tienes pedidos.</h2><p>Cuando confirmes tu primera compra la encontrarás aquí.</p><a href="tienda.html" class="btn btn-gold">Ver colección</a></div>'}</div></section>`}
const date=s=>{try{return new Date(s).toLocaleDateString('es-CO',{year:'numeric',month:'long',day:'numeric'})}catch{return''}};
async function orderDetail(){let codigo=new URLSearchParams(location.search).get('codigo');if(!db.user)return `${head('Inicia sesión')}<div class="container section"><a class="btn btn-gold" href="login.html">Iniciar sesión</a></div>`;let o=await db.getOrder(codigo||'');if(!o||!(o.user_id===db.user.id||db.profile?.rol==='ADMIN'))return `${head('Pedido no encontrado')}<div class="container section"><a href="pedidos.html">Ir a mis pedidos</a></div>`;let wa=orderWhatsapp(o);return `${head(`Pedido <em>${safe(o.codigo)}</em>`,'DETALLE DEL PEDIDO',`Registrado el ${date(o.created_at)}`)}<section class="section"><div class="container order-detail"><div class="form-card"><div class="order-head"><h2>Estado de tu pedido</h2>${orderBadge(o.estado)}</div><p>El pago y el envío deben ser confirmados por la tienda.</p><div class="detail-line"></div><h3>Productos</h3>${(o.order_items||[]).map(i=>`<div class="checkout-item"><span>${i.cantidad} × ${safe(i.products?.nombre||'Producto')} · ${money(i.precio_unitario)}</span><strong>${money(i.subtotal)}</strong></div>`).join('')}<div class="summary-total"><span>Total</span><strong>${money(o.total)}</strong></div>${wa?`<a class="btn btn-gold" href="${wa}" target="_blank" rel="noopener">Coordinar por WhatsApp ${ico('arrow',17)}</a>`:'<p class="small-muted">Configura el WhatsApp comercial en assets/js/config.js para habilitar el botón de coordinación.</p>'}</div><aside class="form-card"><h2>Datos de entrega</h2><p><b>Nombre:</b> ${safe(o.nombre)}</p><p><b>Teléfono:</b> ${safe(o.telefono)}</p><p><b>Ciudad:</b> ${safe(o.ciudad)}</p><p><b>Dirección:</b> ${safe(o.direccion)}</p><p><b>Observaciones:</b> ${safe(o.nota||'Ninguna')}</p><a href="pedidos.html" class="text-link dark-link">${ico('arrow',17)} Volver a mis pedidos</a></aside></div></section>`}
function about(){return `${head('Una firma <em>inolvidable.</em>','OUR STORY','Un espacio creado para descubrir el arte que vive dentro de cada fragancia.')}<section class="section"><div class="container about-grid"><div class="about-art"><div class="about-monogram">K</div><span>THE ART OF FRAGRANCE</span></div><div class="about-text"><p class="eyebrow">EL ESPÍRITU KINGSEDUCCION</p><h2>El lujo no siempre se ve. <em>A veces se siente.</em></h2><p>KingSeduccion es una propuesta de tienda de perfumería que reúne catálogo, búsqueda personalizada y una experiencia digital pensada para acompañar cada descubrimiento.</p><p>La colección se administra desde un panel centralizado: marcas, presentaciones, precios y disponibilidad. Cada compra queda registrada para ofrecer seguimiento y reconocimiento a los clientes.</p><div class="about-note">Nuestra selección final dependerá del inventario que se cargue en la tienda. Las fragancias del modo demostración son ficticias.</div><a href="tienda.html" class="btn btn-gold">Conoce la colección ${ico('arrow',17)}</a></div></div></section>`}
function adminNav(){const labels=[['dashboard','Vista general','spark'],['productos','Catálogo e inventario','settings'],['pedidos','Pedidos y entregas','bag'],['movimientos','Movimientos','clock'],['actividad','Auditoría','shield'],['clientes','Clientes','user'],['reportes','Analítica y ventas','star']];return `<aside class="admin-sidebar"><div class="admin-sidebar-head"><div class="admin-sidebar-logo">K<span>✦</span></div><div><b>KINGSEDUCCION</b><small>STUDIO / ADMIN</small></div></div><div class="admin-sidebar-title">ESPACIO DE TRABAJO</div>${labels.map(([k,name,icon])=>`<a class="admin-menu ${activeAdminTab===k?'active':''}" href="admin.html?tab=${k}">${ico(icon,18)} <span>${name}</span></a>`).join('')}<div class="admin-sidebar-bottom"><a class="admin-menu" href="tienda.html">${ico('arrow',17)} Ver la tienda</a><button class="admin-menu admin-logout" type="button" data-action="logout">${ico('x',17)} Cerrar sesión</button></div></aside>`}
async function admin(){if(!db.user){return `${head('KingSeduccion <em>Studio.</em>','ÁREA PRIVADA','Control de inventario, ventas y clientes en un solo lugar.')}<section class="section"><div class="container admin-gate"><div class="admin-gate-art"><span class="gate-eyebrow">KINGSEDUCCION / PRIVATE ACCESS</span><strong>El arte de gestionar con precisión.</strong><p>Una experiencia administrativa creada para controlar cada detalle de tu perfumería, con datos sincronizados en Supabase.</p><div class="gate-decoration">K<span>✦</span></div></div><div class="admin-gate-form"><span class="eyebrow">ACCESO RESTRINGIDO</span><h2>Bienvenido al <em>Studio.</em></h2><p>Ingresa con tu usuario autorizado en Supabase.</p><form id="login-form"><label>Correo electrónico<input name="email" type="email" required autocomplete="username" placeholder="tu@correo.com"></label><label>Contraseña<input name="password" type="password" required minlength="6" autocomplete="current-password" placeholder="Tu contraseña"></label><button class="btn btn-gold full" type="submit">Acceder al panel ${ico('arrow',17)}</button></form><p class="gate-hint">¿Todavía no tienes cuenta? <a href="registro.html">Regístrate aquí</a>. Para administrar, el rol ADMIN debe ser autorizado en la base de datos.</p><a class="gate-back" href="index.html">← Volver a la tienda</a></div></div></section>`}if(db.profile?.rol!=='ADMIN'){return `${head('Acceso <em>restringido.</em>','PERMISOS','Tu sesión está activa, pero esta cuenta no tiene permisos de administrador.')}<section class="section"><div class="container auth-needed"><h2>Cuenta de cliente</h2><p>Ingresaste como <b>${safe(db.profile?.email||db.user.email||'Cliente')}</b>. Es necesario que un responsable autorice el rol ADMIN en Supabase. No compartas contraseñas.</p><div class="gate-actions"><a class="btn btn-outline-dark" href="cuenta.html">Ir a mi cuenta</a><button class="btn btn-gold" data-action="logout">Salir de la sesión</button></div></div></section>`}
 let body='';if(activeAdminTab==='dashboard')body=await adminDashboard();else if(activeAdminTab==='productos')body=await adminProducts();else if(activeAdminTab==='pedidos')body=await adminOrders();else if(activeAdminTab==='movimientos')body=await adminMoves();else if(activeAdminTab==='actividad')body=await adminActivity();else if(activeAdminTab==='clientes')body=await adminClients();else if(activeAdminTab==='reportes')body=await adminReports();else body=await adminDashboard();
 return `<section class="admin-page"><div class="container admin-top"><div><p class="eyebrow">KINGSEDUCCION / ADMINISTRACIÓN</p><h1>Centro de <em>control.</em></h1></div><span class="admin-user">${ico('shield',17)} ${safe(db.profile.nombre||'Administrador')}</span></div><div class="container admin-layout">${adminNav()}<main class="admin-main">${body}</main></div></section>`}
async function adminDashboard(){const orders=await db.getOrders(true),a=catalog,paid=orders.filter(o=>['pagado','entregado'].includes(o.estado)),sales=paid.reduce((s,o)=>s+Number(o.total||0),0),pending=orders.filter(o=>o.estado==='nuevo'),low=a.filter(p=>p.activo&&Number(p.stock)>0&&p.stock<=5);const noPrice=a.filter(p=>retail(p)==null||Number(retail(p))<=0),noWholesale=a.filter(p=>wholesale(p)==null||Number(wholesale(p))<=0),noImage=a.filter(p=>!p.imagen_url),noStock=a.filter(p=>p.stock<=0),ready=a.filter(p=>available(p));const recent=orders.slice(0,6);const ratio=a.length?Math.round(ready.length/a.length*100):0;return `<div class="admin-title-row"><div><span class="admin-overline">DASHBOARD / EN TIEMPO REAL</span><h2>Tu negocio, en perspectiva.</h2><p>Resumen de KingSeduccion conectado a Supabase.</p></div><span class="admin-date">${date(new Date().toISOString())}</span></div><div class="stats-grid admin-stats"><div class="stat-box"><span>Ventas confirmadas</span><strong>${money(sales)}</strong><small>${paid.length} compras pagadas</small>${ico('bag',22)}</div><div class="stat-box"><span>Pedidos recibidos</span><strong>${orders.length}</strong><small>${pending.length} por gestionar</small>${ico('clock',22)}</div><div class="stat-box"><span>Referencias del catálogo</span><strong>${a.length}</strong><small>${ready.length} listas para vender</small>${ico('spark',22)}</div><div class="stat-box"><span>Unidades en inventario</span><strong>${a.reduce((s,p)=>s+Number(p.stock||0),0)}</strong><small>${low.length} con stock bajo</small>${ico('settings',22)}</div></div><div class="admin-spotlight"><div><span class="admin-overline">SALUD DEL CATÁLOGO</span><h3>${ratio}% de referencias listas para vender</h3><p>Una referencia se considera lista cuando tiene precio y al menos una unidad disponible.</p><div class="readiness-track"><span style="width:${ratio}%"></span></div><div class="readiness-legend"><span>${ready.length} listas</span><span>${a.length-ready.length} por completar</span></div></div><a href="admin.html?tab=productos" class="btn btn-gold">Completar catálogo ${ico('arrow',16)}</a></div><div class="admin-pill-stats"><a href="admin.html?tab=productos&vista=precio"><strong>${noPrice.length}</strong><span>Sin precio detal</span>${ico('arrow',17)}</a><a href="admin.html?tab=productos&vista=stock"><strong>${noStock.length}</strong><span>Sin existencias</span>${ico('arrow',17)}</a><a href="admin.html?tab=productos&vista=foto"><strong>${noImage.length}</strong><span>Sin fotografía</span>${ico('arrow',17)}</a></div><div class="admin-two"><div class="admin-panel"><div class="panel-head"><h3>Últimos pedidos</h3><a href="admin.html?tab=pedidos">Ver todos ${ico('arrow',15)}</a></div>${recent.length?`<div class="table-scroll"><table><thead><tr><th>Código</th><th>Total</th><th>Estado</th></tr></thead><tbody>${recent.map(o=>`<tr><td>${safe(o.codigo)}</td><td>${money(o.total)}</td><td>${orderBadge(o.estado)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="admin-empty"><span>✦</span><b>Aún no hay pedidos</b><p>Las compras de tus clientes aparecerán aquí.</p></div>'}</div><div class="admin-panel"><div class="panel-head"><h3>Alertas de inventario</h3><a href="admin.html?tab=productos">Gestionar ${ico('arrow',15)}</a></div>${low.length?low.slice(0,6).map(p=>`<div class="mini-inventory"><span>${safe(p.nombre)}</span><strong>${p.stock} uds.</strong></div>`).join(''):'<div class="admin-empty"><span>✓</span><b>Sin alertas críticas</b><p>Las referencias sin stock están identificadas en el resumen superior.</p></div>'}</div></div>`}
const productEmpty={id:'',sku:'',nombre:'',marca:'Sin especificar',genero:'Sin especificar',familia:'Perfume',precio:null,precio_detal:null,precio_mayor:null,minimo_mayor:6,stock:0,notas:'',descripcion:'',ocasion:'Sin especificar',clima:'TODOS',presentacion_ml:null,concentracion:'Sin especificar',imagen_url:'',activo:true,destacado:false};
function productForm(p=productEmpty){
 const edit=Boolean(p.id),stock=Number(p.stock)||0;
 const families=[...new Set([...window.KING_FAMILIES,...catalog.map(x=>x.familia),'Perfume','Envase con caja','Kit','Estuche','Trío','Variedad de perfumes','Miniaturas','Presentación múltiple'])];
 const options=(list,value)=>list.map(f=>`<option value="${safe(f)}" ${f===value?'selected':''}>${safe(f)}</option>`).join('');
 return `<form id="admin-product-form" class="admin-panel product-form" autocomplete="off" action="javascript:void(0)" onsubmit="return false">
 <div class="panel-head edit-heading"><div><div class="eyebrow">${edit?'EDITANDO REFERENCIA':'NUEVA REFERENCIA'}</div><h3>${edit?safe(p.nombre):'Crear producto'}</h3><span class="edit-sku">${edit?'Código: '+safe(p.sku):'Completa los datos de tu perfume'}</span></div>${edit?`<button type="button" class="subtle-button" data-action="new-product">+ Nuevo</button>`:''}</div>
 <input type="hidden" name="id" value="${safe(p.id)}">
 <section class="editor-block"><div class="editor-block-heading"><b>01</b><span>Información del perfume</span></div>
 <div class="field-grid">
 <label>Código SKU <input name="sku" required maxlength="48" value="${safe(p.sku)}" placeholder="P001"></label>
 <label>Nombre del perfume <input name="nombre" required maxlength="180" value="${safe(p.nombre)}" placeholder="Nombre del producto"></label>
 <label>Marca <input name="marca" required maxlength="100" value="${safe(p.marca)}"></label>
 <label>Género <select name="genero">${options(['Sin especificar','Hombre','Mujer','Unisex'],p.genero)}</select></label>
 <label>Familia <select name="familia">${options(families,p.familia)}</select></label>
 <label>Concentración <select name="concentracion">${options(['Sin especificar','Eau de Toilette','Eau de Parfum','Parfum','Extrait de Parfum','Cologne','Otros'],p.concentracion)}</select></label>
 </div></section>
 <section class="editor-block editor-prices"><div class="editor-block-heading"><b>02</b><span>Precios e inventario</span></div>
 <p class="editor-helper">Puedes escribir 85000, 85.000 o $85.000. Los valores se guardan en pesos colombianos.</p>
 <div class="price-field-grid">
 <label>Precio al detal (COP)<input name="precio_detal" type="text" inputmode="decimal" placeholder="85000" value="${retail(p)==null?'':Number(retail(p))}"></label>
 <label>Precio al mayor (COP)<input name="precio_mayor" type="text" inputmode="decimal" placeholder="65000" value="${wholesale(p)==null?'':Number(wholesale(p))}"></label>
 <label>Mínimo para mayor<input name="minimo_mayor" type="number" min="2" max="20" step="1" required value="${wholesaleMinimum(p)}"></label>
 <label>Unidades en stock<input name="stock" type="number" min="0" step="1" required value="${stock}"></label>
 </div><small class="editor-hint">El precio mayorista se aplica automáticamente a partir de la cantidad indicada. Los productos sin precio detal o stock no permiten comprar.</small>
 </section>
 <section class="editor-block"><div class="editor-block-heading"><b>03</b><span>Presentación y fotografía</span></div>
 <div class="field-grid">
 <label>Presentación en ml <input name="presentacion_ml" type="number" min="1" max="1000" placeholder="Opcional" value="${p.presentacion_ml==null?'':Number(p.presentacion_ml)}"></label>
 <label>Ocasión <select name="ocasion">${options([...new Set(['Sin especificar','Diario','Trabajo','Noche / Evento',p.ocasion||'Sin especificar'])],p.ocasion)}</select></label>
 <label>Clima <select name="clima">${[['TODOS','Todos'],['CALIDO','Cálido'],['FRIO','Frío']].map(([v,t])=>`<option value="${v}" ${v===p.clima?'selected':''}>${t}</option>`).join('')}</select></label>
 <label>URL de imagen <input name="imagen_url" value="${safe(p.imagen_url||'')}" placeholder="https://..."></label>
 </div>
 <label class="editor-wide">Subir fotografía (JPG, PNG o WebP; máximo 4 MB)<input type="file" name="foto" accept="image/png,image/jpeg,image/webp"></label>
 <label class="editor-wide">Notas olfativas<input name="notas" maxlength="300" value="${safe(p.notas)}" placeholder="Vainilla, cedro, cítricos..."></label>
 <label class="editor-wide">Descripción<textarea name="descripcion" rows="3" maxlength="800">${safe(p.descripcion)}</textarea></label>
 </section>
 <section class="editor-block"><div class="editor-block-heading"><b>04</b><span>Publicación</span></div>
 <div class="check-row"><label><input name="activo" type="checkbox" ${p.activo!==false?'checked':''}> Visible en la tienda</label><label><input name="destacado" type="checkbox" ${p.destacado?'checked':''}> Destacado en inicio</label></div>
 </section>
 <div class="editor-footer"><button class="btn btn-gold admin-save-button" type="button" data-action="save-admin-product">${ico('check',18)} ${edit?'Guardar edición':'Crear perfume'}</button>
 <p id="admin-save-status" class="admin-save-status" role="status" aria-live="assertive">${edit?'Los cambios se enviarán a Supabase y se comprobarán antes de confirmarse.':'Completa los datos y guarda el nuevo perfume.'}</p>
 <a class="preview-inline" href="${edit?`producto.html?id=${encodeURIComponent(p.id)}`:'tienda.html'}" target="_blank" rel="noopener">${edit?'Ver este perfume en el catálogo':'Abrir catálogo'} ↗</a></div>
 </form>`;
}

async function adminProducts(){const noPrice=catalog.filter(x=>retail(x)==null||Number(retail(x))<=0).length,noMayor=catalog.filter(x=>wholesale(x)==null||Number(wholesale(x))<=0).length,lowStock=catalog.filter(x=>x.stock<=0).length,noPhoto=catalog.filter(x=>!x.imagen_url).length;return `<div class="admin-title-row"><div><span class="admin-overline">PRODUCTOS / ORGANIZA TU COLECCIÓN</span><h2>Catálogo e inventario</h2><p>Gestiona tus ${catalog.length} referencias, fotografías, precios y existencias.</p></div><div class="admin-title-actions"><button class="btn btn-outline-dark" type="button" data-action="refresh-products">${ico('clock',16)} Actualizar desde Supabase</button><button class="btn btn-outline-dark" type="button" data-action="export-csv">${ico('download',16)} Exportar inventario</button></div></div><div class="admin-inventory-kpis"><div><span>Total de referencias</span><strong>${catalog.length}</strong></div><div><span>Sin precio detal</span><strong>${noPrice}</strong></div><div><span>Sin stock</span><strong>${lowStock}</strong></div><div><span>Sin precio mayor</span><strong>${noMayor}</strong></div></div><div id="admin-catalog-sync-status" class="admin-catalog-sync-status" role="status" aria-live="polite"><span class="sync-dot"></span> Datos de Supabase · Los cambios guardados también se reflejan en el catálogo público.</div><div class="admin-two admin-products-layout"><div id="admin-product-editor">${productForm()}</div><div class="admin-panel admin-products-panel"><div class="panel-head"><h3>Explorar inventario</h3><button class="subtle-button" type="button" data-action="new-product">${ico('spark',14)} Nuevo</button></div><div class="admin-filter-stack"><label class="admin-search-label">${ico('search',18)}<input class="simple-search" id="admin-product-search" value="${safe(adminSearch)}" placeholder="Buscar nombre, marca o SKU..." autocomplete="off"></label><select id="admin-status-filter" class="admin-filter-select" aria-label="Filtrar estado"><option value="all" ${adminView==='all'?'selected':''}>Todos los productos</option><option value="precio" ${adminView==='precio'?'selected':''}>Sin precio detal</option><option value="mayor" ${adminView==='mayor'?'selected':''}>Sin precio mayor</option><option value="stock" ${adminView==='stock'?'selected':''}>Sin stock</option><option value="foto" ${adminView==='foto'?'selected':''}>Sin fotografía</option><option value="disponibles" ${adminView==='disponibles'?'selected':''}>Listos para vender</option><option value="ocultos" ${adminView==='ocultos'?'selected':''}>Archivados</option></select></div><div id="admin-product-result" class="admin-result-hint"></div><div id="admin-product-list"></div><div id="admin-product-pages" class="admin-pager"></div></div></div><div class="admin-panel csv-panel"><div class="panel-head"><h3>Actualizar detal y mayor en bloque</h3><span class="soft-tag">EXCEL / CSV</span></div><p>Completa los campos <b>precio_detal</b>, <b>precio_mayor</b> y <b>minimo_mayor</b> de tu Excel. Se sincroniza usando el SKU, sin borrar datos cuando dejes una celda vacía.</p><div class="csv-buttons"><a class="btn btn-outline-dark" href="plantillas/KingSeduccion_678_Precios_Detal_y_Mayor.xlsx" download>${ico('download',15)} Descargar Excel de 678 perfumes</a><a class="btn btn-outline-dark" href="plantillas/KingSeduccion_678_Precios_Detal_y_Mayor.csv" download>Descargar CSV</a><form id="csv-import-form"><input type="file" name="archivo" accept=".csv,.xlsx,.xls,text/csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" required><button class="btn btn-gold" type="submit">Subir precios y actualizar</button></form></div><p id="csv-import-progress" class="form-help" aria-live="polite">Los cambios se guardan de forma segura con tu cuenta ADMIN. Las referencias sin precio y stock no se pueden comprar.</p></div>`}
function adminProductRows(arr){return arr.length?`<div class="table-scroll"><table class="admin-catalog-table"><thead><tr><th>Producto</th><th>Precio detal</th><th>Precio mayor</th><th>Stock</th><th>Visibilidad</th><th>Acciones</th></tr></thead><tbody>${arr.map(p=>`<tr><td><div class="admin-product-identity"><div class="admin-mini-photo">${p.imagen_url?`<img src="${url(p.imagen_url)}" alt="">`:'✦'}</div><div><strong>${safe(p.nombre)}</strong><small>${safe(p.sku)} · ${safe(p.marca)}</small></div></div></td><td><span class="${retail(p)==null?'admin-missing':''}">${money(retail(p))}</span></td><td><span class="${wholesale(p)==null?'admin-missing':''}">${money(wholesale(p))}</span><small>Desde ${wholesaleMinimum(p)} uds</small></td><td><span class="stock-indicator ${p.stock<=0?'is-empty':p.stock<=5?'is-low':'is-good'}">${Number(p.stock)||0} uds.</span></td><td><span class="soft-tag ${p.activo?'':'muted-tag'}">${p.activo?'Visible':'Archivado'}</span></td><td class="table-actions"><button type="button" data-action="edit-product" data-id="${safe(p.id)}">Editar</button><button type="button" data-action="archive-product" data-id="${safe(p.id)}">${p.activo?'Ocultar':'Activar'}</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="admin-empty"><span>⌕</span><b>Sin resultados</b><p>Prueba con otros filtros o términos de búsqueda.</p></div>'}
function adminFilteredProducts(){const q=adminSearch.toLocaleLowerCase('es-CO');return catalog.filter(p=>(`${p.sku||''} ${p.nombre||''} ${p.marca||''}`.toLocaleLowerCase('es-CO').includes(q))&&(adminView==='all'||(adminView==='precio'&&(retail(p)==null||Number(retail(p))<=0))||(adminView==='mayor'&&(wholesale(p)==null||Number(wholesale(p))<=0))||(adminView==='stock'&&Number(p.stock)<=0)||(adminView==='foto'&&!p.imagen_url)||(adminView==='disponibles'&&available(p))||(adminView==='ocultos'&&p.activo===false)))}
function renderAdminProductTable(){const container=$('#admin-product-list');if(!container)return;const results=adminFilteredProducts(),pages=Math.max(1,Math.ceil(results.length/adminPageSize));adminPageNumber=Math.max(1,Math.min(adminPageNumber,pages));const start=(adminPageNumber-1)*adminPageSize;container.innerHTML=adminProductRows(results.slice(start,start+adminPageSize));const status=$('#admin-product-result');if(status)status.textContent=`${results.length} resultados · Mostrando ${results.length?start+1:0}–${Math.min(results.length,start+adminPageSize)}`;const pager=$('#admin-product-pages');if(pager)pager.innerHTML=pages>1?`<button type="button" data-action="admin-page" data-number="${adminPageNumber-1}" ${adminPageNumber===1?'disabled':''}>${ico('arrow',14)} Anterior</button><span>Página ${adminPageNumber} de ${pages}</span><button type="button" data-action="admin-page" data-number="${adminPageNumber+1}" ${adminPageNumber===pages?'disabled':''}>Siguiente ${ico('arrow',14)}</button>`:''}
async function adminOrders(){let orders=await db.getOrders(true);return `<div class="admin-title-row"><div><h2>Gestión de pedidos</h2><p>Confirma pagos, controla entregas y edita cantidades de pedidos nuevos.</p></div></div><div class="admin-panel"><div class="panel-head"><h3>Pedidos (${orders.length})</h3><label class="compact-select">Filtrar: <select id="admin-order-filter"><option value="">Todos</option>${window.KING_ORDER_STATES.map(s=>`<option value="${s}">${stateLabel(s)}</option>`).join('')}</select></label></div><div class="table-scroll"><table><thead><tr><th>Código / Fecha</th><th>Cliente</th><th>Total</th><th>Estado</th><th>Detalle</th></tr></thead><tbody id="admin-orders-table">${adminOrderRows(orders)}</tbody></table></div></div><div id="admin-order-edit"></div>`}
function adminOrderRows(rows){return rows.length?rows.map(o=>`<tr data-order-status="${safe(o.estado)}"><td><strong>${safe(o.codigo)}</strong><small>${date(o.created_at)}</small></td><td>${safe(o.nombre)}<small>${safe(o.telefono)}</small></td><td>${money(o.total)}</td><td>${orderBadge(o.estado)}</td><td><button class="table-action-primary" data-action="edit-order" data-id="${safe(o.id)}">Gestionar ${ico('arrow',15)}</button></td></tr>`).join(''):'<tr><td colspan="5">No hay pedidos registrados.</td></tr>'}
async function openOrderEditor(id){const orders=await db.getOrders(true),o=orders.find(x=>x.id===id);if(!o)throw Error('Pedido no encontrado');let editable=o.estado==='nuevo';$('#admin-order-edit').innerHTML=`<div class="admin-panel order-editor" id="order-editor"><div class="panel-head"><h3>Pedido ${safe(o.codigo)}</h3><button class="subtle-button" data-action="close-order">Cerrar</button></div><p>${safe(o.nombre)} · ${safe(o.telefono)} · ${safe(o.ciudad)}</p><p><b>Dirección:</b> ${safe(o.direccion)}</p><p><b>Estado:</b> ${orderBadge(o.estado)}</p><form id="admin-order-form"><input type="hidden" name="id" value="${safe(o.id)}"><h4>Productos ${editable?'(edita las cantidades)':''}</h4><div class="order-item-edit">${(o.order_items||[]).map(i=>`<label><span>${safe(i.products?.nombre||i.product_id)}</span><span>${money(i.precio_unitario)} / unidad</span><input type="number" data-order-product="${safe(i.product_id)}" value="${i.cantidad}" min="1" max="20" ${!editable?'disabled':''}></label>`).join('')}</div><label>Nota interna / observaciones<textarea name="nota" rows="3" maxlength="500">${safe(o.nota||'')}</textarea></label><label>Actualizar estado<select name="estado"><option value="">Conservar: ${stateLabel(o.estado)}</option>${o.estado==='nuevo'?'<option value="pagado">Pago confirmado</option><option value="cancelado">Cancelar y liberar stock</option>':''}${o.estado==='pagado'?'<option value="entregado">Marcar entregado</option>':''}</select></label><p class="form-help">Los puntos del club se asignan cuando el estado pasa a pagado. No podrás cancelar desde aquí un pedido pagado.</p><button class="btn btn-gold" type="submit">Guardar cambios ${ico('check',17)}</button></form></div>`;$('#order-editor').scrollIntoView({behavior:'smooth',block:'start'})}
async function adminMoves(){let moves=await db.getMovements(),mp=new Map(catalog.map(p=>[p.id,p]));return `<div class="admin-title-row"><div><h2>Movimientos de inventario</h2><p>Consulta entradas, salidas y ajustes.</p></div></div><div class="admin-panel"><div class="table-scroll"><table><thead><tr><th>Fecha</th><th>Producto</th><th>Movimiento</th><th>Motivo</th></tr></thead><tbody>${moves.length?moves.map(m=>`<tr><td>${date(m.created_at)}</td><td>${safe(m.products?.nombre||mp.get(m.product_id)?.nombre||m.product_id)}</td><td class="${m.cantidad<0?'low-stock':'positive'}">${m.cantidad>0?'+':''}${m.cantidad}</td><td>${safe(m.motivo)}</td></tr>`).join(''):'<tr><td colspan="4">Todavía no hay movimientos.</td></tr>'}</tbody></table></div></div>`}
async function adminActivity(){const records=await db.getAdminActivity();return `<div class="admin-title-row"><div><span class="admin-overline">TRANSPARENCIA / CONTROL</span><h2>Registro de actividad</h2><p>Consulta los cambios realizados en productos y pedidos. El registro se guarda en Supabase.</p></div></div><div class="admin-panel"><div class="panel-head"><h3>Últimos movimientos del sistema</h3><span class="soft-tag">${records.length} eventos</span></div><div class="table-scroll"><table><thead><tr><th>Fecha</th><th>Acción</th><th>Referencia</th><th>Detalle</th></tr></thead><tbody>${records.length?records.map(x=>`<tr><td>${date(x.created_at)}</td><td><span class="soft-tag">${safe(x.tipo.replaceAll('_',' '))}</span></td><td>${safe(x.detalle?.sku||x.detalle?.codigo||'—')}</td><td>${x.tipo==='pedido_estado'?`${safe(x.detalle?.estado_anterior||'')} → ${safe(x.detalle?.estado_nuevo||'')}`:x.tipo==='producto_nuevo'?`${safe(x.detalle?.nombre||'')} · ${money(x.detalle?.precio_detal??x.detalle?.precio)}`:`${safe(x.detalle?.nombre||'')} · ${money(x.detalle?.precio_detal_antes??x.detalle?.precio_antes)} → ${money(x.detalle?.precio_detal_despues??x.detalle?.precio_despues)} · Mayor ${money(x.detalle?.precio_mayor_antes)} → ${money(x.detalle?.precio_mayor_despues)} · Stock ${Number(x.detalle?.stock_antes||0)} → ${Number(x.detalle?.stock_despues||0)}`}</td></tr>`).join(''):'<tr><td colspan="4">No hay cambios registrados desde la activación del historial.</td></tr>'}</tbody></table></div><p class="audit-hint">Se registran cambios en nombre, precio, existencias, visibilidad, fotografía y estado de pedidos. Los registros no se pueden editar desde la web.</p></div>`}
async function adminClients(){let profiles=await db.getProfiles();return `<div class="admin-title-row"><div><h2>Clientes registrados</h2><p>Consulta perfiles y puntos del Club KingSeduccion.</p></div></div><div class="admin-panel"><div class="table-scroll"><table><thead><tr><th>Nombre</th><th>Correo</th><th>Tipo</th><th>Puntos</th></tr></thead><tbody>${profiles.map(p=>`<tr><td>${safe(p.nombre)}</td><td>${safe(p.email)}</td><td>${safe(p.rol)}</td><td>${Number(p.puntos||0)}</td></tr>`).join('')}</tbody></table></div><p class="form-help">Los roles administrativos solo pueden asignarse desde el editor SQL seguro de Supabase.</p></div>`}
async function adminReports(){let orders=await db.getOrders(true),paid=orders.filter(o=>['pagado','entregado'].includes(o.estado)),tot=paid.reduce((s,o)=>s+Number(o.total),0),groups={};paid.forEach(o=>{let k=new Date(o.paid_at||o.created_at).toLocaleDateString('es-CO',{year:'numeric',month:'short',timeZone:'America/Bogota'});groups[k]=(groups[k]||0)+Number(o.total)});let biggest=Math.max(1,...Object.values(groups));return `<div class="admin-title-row"><div><h2>Reportes de ventas</h2><p>Ingresos registrados por pedidos pagados o entregados.</p></div><button data-action="export-orders" class="btn btn-outline-dark">${ico('download',17)} Descargar reporte</button></div><div class="stats-grid"><div class="stat-box"><span>Ventas confirmadas</span><strong>${money(tot)}</strong></div><div class="stat-box"><span>Órdenes pagadas</span><strong>${paid.length}</strong></div><div class="stat-box"><span>Ticket promedio</span><strong>${money(paid.length?tot/paid.length:0)}</strong></div><div class="stat-box"><span>Pedidos pendientes</span><strong>${orders.filter(x=>x.estado==='nuevo').length}</strong></div></div><div class="admin-panel"><h3>Ventas por mes</h3><div class="bar-chart">${Object.keys(groups).length?Object.entries(groups).map(([k,v])=>`<div class="bar-row"><span>${safe(k)}</span><div><i style="width:${Math.max(2,Math.round(v/biggest*100))}%"></i></div><strong>${money(v)}</strong></div>`).join(''):'<div class="empty">Las ventas confirmadas aparecerán aquí.</div>'}</div></div>`}
function csvEscape(s){let v=String(s??'');return /[,;"\n\r]/.test(v)?'"'+v.replace(/"/g,'""')+'"':v}
function downloadCsv(name,columns,rows){let data=[columns.join(','),...rows.map(r=>r.map(csvEscape).join(','))].join('\r\n');let a=document.createElement('a'),u=URL.createObjectURL(new Blob(['\uFEFF'+data],{type:'text/csv;charset=utf-8'}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1500)}
function parseCSV(raw){let rows=[],row=[],value='',quoted=false;raw=raw.replace(/^\uFEFF/,'');let delimiter=raw.split(/\r?\n/,1)[0].includes(';')?';':',';for(let i=0;i<raw.length;i++){const c=raw[i];if(c==='"'){if(quoted&&raw[i+1]==='"'){value+='"';i++}else quoted=!quoted}else if(c===delimiter&&!quoted){row.push(value.trim());value=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&raw[i+1]==='\n')i++;row.push(value.trim());if(row.some(Boolean))rows.push(row);row=[];value=''}else value+=c}row.push(value.trim());if(row.some(Boolean))rows.push(row);if(quoted)throw Error('El CSV tiene comillas sin cerrar.');let cols=rows.shift()?.map(x=>x.toLowerCase().replace(/\s+/g,'_'))||[];return rows.map(r=>Object.fromEntries(cols.map((c,i)=>[c,r[i]||''])))}
async function parsePriceFile(file){if(/\.xlsx?$/i.test(file.name)){if(!window.XLSX)throw Error('No cargó el lector de Excel. Revisa Internet o guarda el archivo en CSV.');const buf=await file.arrayBuffer();const book=window.XLSX.read(buf,{type:'array'});const name=book.SheetNames[0];if(!name)throw Error('El Excel no tiene hojas.');return window.XLSX.utils.sheet_to_json(book.Sheets[name],{defval:'',raw:false});}return parseCSV(await file.text())}
function parseProductCSV(r,i){
 const norm=Object.fromEntries(Object.entries(r).map(([k,v])=>[String(k).normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toLowerCase().replace(/[\s-]+/g,'_'),v]));
 const val=k=>String(norm[k]??'').trim();
 if(!val('sku'))throw Error(`Fila ${i+2}: falta SKU.`);
 const p={sku:val('sku')};
 for(const k of ['nombre','marca','genero','familia','notas','descripcion','ocasion','clima','concentracion','imagen_url'])if(val(k))p[k]=val(k);
 const num=raw=>{let z=String(raw).replace(/\s|\$/g,'');if(z.includes('.')&&z.includes(','))z=z.lastIndexOf(',')>z.lastIndexOf('.')?z.replace(/\./g,'').replace(',','.'):z.replace(/,/g,'');else if(/^\d{1,3}(\.\d{3})+$/.test(z))z=z.replace(/\./g,'');else if(/^\d{1,3}(,\d{3})+$/.test(z))z=z.replace(/,/g,'');else z=z.replace(',','.');return Number(z)};
 for(const k of ['precio_detal','precio_mayor','minimo_mayor','stock','presentacion_ml']){
   let raw=k==='precio_detal'?val('precio_detal')||val('precio')||val('precio_al_detal'):k==='precio_mayor'?val('precio_mayor')||val('precio_al_mayor'):val(k);
   if(!raw)continue;
   let n=num(raw),whole=Number.isInteger(n);
   if(!Number.isFinite(n)||!whole||(k.startsWith('precio')&&n<=0)||(k==='stock'&&n<0)||(k==='minimo_mayor'&&(n<2||n>20))||(k==='presentacion_ml'&&(n<1||n>1000)))throw Error(`Fila ${i+2}: ${k} inválido.`);
   p[k]=n;
 }
 if('precio_detal' in p)p.precio=p.precio_detal;
 for(const k of ['activo','destacado'])if(val(k))p[k]=['true','1','si','sí','yes'].includes(val(k).toLowerCase());
 return p;
}
function mutateCart(id,step){let p=catalog.find(p=>p.id===id);if(!available(p))throw Error('Este producto aún no tiene precio o existencias confirmadas.');let cart=cartGet(),row=cart.find(x=>x.id===id);if(!row&&step>0)cart.push({id,cantidad:1});else if(row){row.cantidad=Math.max(0,Math.min(20,p.stock,row.cantidad+step));cart=cart.filter(x=>x.cantidad>0);if(step>0&&(row.cantidad>=p.stock||row.cantidad>=20))toast('Máximo permitido: 20 unidades por referencia y pedido.')}cartSet(cart)}
async function action(button){const kind=button.dataset.action,id=button.dataset.id;switch(kind){
 case 'add':mutateCart(id,1);toast('¡Fragancia añadida al carrito!');break;
 case 'shop-page':currentShopPage=Number(button.dataset.page)||1;filterProducts();$('#catalog-products')?.scrollIntoView({behavior:'smooth',block:'start'});break;
 case 'qty':mutateCart(id,Number(button.dataset.step));root.innerHTML=header()+await cart()+footer();break;
 case 'remove':cartSet(cartGet().filter(x=>x.id!==id));root.innerHTML=header()+await cart()+footer();toast('Producto retirado.');break;
 case 'fav':favIds=await db.toggleFavorite(id);button.classList.toggle('is-active',favIds.includes(id));toast(favIds.includes(id)?'Guardado en tus favoritos':'Eliminado de tus favoritos');if(page==='favoritos')root.innerHTML=header()+await favoritePage()+footer();break;
 case 'demo-login':await db.loginDemo(button.dataset.role);location.href=page==='admin'?'admin.html':(new URLSearchParams(location.search).get('next')||'cuenta.html');break;
 case 'logout':await db.logout();location.href='index.html';break;
 case 'save-admin-product':{
   // La edición se hace vía JS: NUNCA dejar que el navegador envíe el formulario y vuelva a Vista general.
   const form=button.closest('#admin-product-form');
   if(!form)throw Error('El formulario de edición no está disponible. Vuelve a seleccionar el perfume.');
   if(form.dataset.saving==='1')return;
   if(!form.reportValidity()){
     const status=form.querySelector('#admin-save-status');
     if(status){status.className='admin-save-status failed';status.textContent='No se guardó: completa los campos obligatorios y revisa los valores.';}
     return;
   }
   form.dataset.saving='1';
   const status=form.querySelector('#admin-save-status');
   if(status){status.className='admin-save-status pending';status.textContent='Guardando cambios en Supabase. Permanece en esta pantalla…';}
   try{await submit(form)}
   catch(err){
     console.error('KingSeduccion: error editando producto',err);
     const msg='No se guardó: '+(err?.message||'Error desconocido')+' · Corrige el dato y vuelve a intentar.';
     const latest=document.querySelector('#admin-product-form #admin-save-status');
     if(latest){latest.className='admin-save-status failed';latest.textContent=msg}
     toast(msg,'error');
   }finally{form.dataset.saving='0'}
   break;
 }
 case 'edit-product':{let p=catalog.find(x=>x.id===id);if(p){$('#admin-product-editor').innerHTML=productForm(p);$('#admin-product-editor').scrollIntoView({behavior:'smooth',block:'start'});$('#admin-product-editor input[name="precio_detal"]')?.focus({preventScroll:true})}break}
 case 'new-product':$('#admin-product-editor').innerHTML=productForm();$('#admin-product-editor').scrollIntoView({behavior:'smooth',block:'start'});break;
 case 'admin-page':adminPageNumber=Number(button.dataset.number)||1;renderAdminProductTable();$('#admin-product-list')?.scrollIntoView({behavior:'smooth',block:'start'});break;
  case 'refresh-products':{catalog=await db.getProducts({admin:true});renderAdminProductTable();const status=$('#admin-catalog-sync-status');if(status){status.classList.add('confirmed');status.innerHTML='<span class="sync-dot"></span> Inventario recargado desde Supabase · '+catalog.length+' referencias · '+new Date().toLocaleTimeString('es-CO')+'.';}toast('Inventario actualizado desde Supabase.');break;}
 case 'archive-product':{let p=catalog.find(x=>x.id===id);if(!confirm(`${p.activo?'Archivar':'Reactivar'} ${p.nombre}?`))return;await db.archive(id,!p.activo);catalog=await db.getProducts({admin:true});renderAdminProductTable();toast('Estado actualizado.');break}
 case 'export-csv':{let cols=['sku','nombre','marca','genero','familia','precio_detal','precio_mayor','minimo_mayor','stock','notas','descripcion','ocasion','clima','presentacion_ml','concentracion','imagen_url','activo','destacado'];downloadCsv('kingseduccion-inventario.csv',cols,catalog.map(p=>cols.map(k=>p[k])));break}
 case 'edit-order':await openOrderEditor(id);break;
 case 'close-order':$('#admin-order-edit').innerHTML='';break;
 case 'export-orders':{let orders=await db.getOrders(true),cols=['codigo','created_at','nombre','telefono','ciudad','total','estado','paid_at'];downloadCsv('kingseduccion-pedidos.csv',cols,orders.map(o=>cols.map(k=>o[k])));break}
 }}
function navigateAfterLogin(){let next=new URLSearchParams(location.search).get('next');return ['checkout.html','cuenta.html','admin.html','pedidos.html','favoritos.html'].includes(next)?next:'cuenta.html'}
async function submit(form){let id=form.getAttribute('id'),fd=new FormData(form),get=k=>String(fd.get(k)||'').trim();switch(id){
 case 'login-form':{await db.login(get('email'),get('password'));toast('Has iniciado sesión.');location.href=page==='admin'?'admin.html':navigateAfterLogin();break}
 case 'register-form':{let d=await db.register(get('nombre'),get('email'),get('password'));toast(d.session?'Cuenta creada, ya puedes ingresar.':'Revisa tu correo y confirma la cuenta.');if(d.session)location.href='cuenta.html';else form.reset();break}
 case 'reset-form':await db.reset(get('email'));toast('Si el correo está registrado, recibirás instrucciones.');break;
 case 'password-form':await db.newPassword(get('password'));toast('Contraseña actualizada.');location.href='login.html';break;
 case 'quiz-form':quizResults(fd);break;
 case 'checkout-form':{let contact={nombre:get('nombre'),telefono:get('telefono'),ciudad:get('ciudad'),direccion:get('direccion'),nota:get('nota')};if(!get('confirm'))throw Error('Acepta las condiciones para continuar.');let items=cartDetails().map(x=>({id:x.p.id,cantidad:x.cantidad})),result=await db.placeOrder(items,contact);cartSet([]);location.href='pedido.html?codigo='+encodeURIComponent(result.codigo);break}
 case 'admin-product-form':{
  const keys=['sku','nombre','marca','genero','familia','stock','notas','descripcion','ocasion','clima','presentacion_ml','concentracion','imagen_url'];
  const obj=Object.fromEntries(keys.map(k=>[k,get(k)]));
  obj.precio_detal=parseCOP(get('precio_detal'));
  obj.precio_mayor=parseCOP(get('precio_mayor'));
  obj.precio=obj.precio_detal;obj.minimo_mayor=Number(get('minimo_mayor'));
  obj.stock=Number(get('stock'));obj.presentacion_ml=get('presentacion_ml')===''?null:Number(get('presentacion_ml'));
  obj.activo=fd.has('activo');obj.destacado=fd.has('destacado');if(get('id'))obj.id=get('id');
  if((obj.precio_detal!==null&&(!Number.isInteger(obj.precio_detal)||obj.precio_detal<=0)) ||
   (obj.precio_mayor!==null&&(!Number.isInteger(obj.precio_mayor)||obj.precio_mayor<=0)) ||
   (obj.precio_mayor!==null&&obj.precio_detal!==null&&obj.precio_mayor>obj.precio_detal) ||
   !Number.isInteger(obj.minimo_mayor)||obj.minimo_mayor<2||obj.minimo_mayor>20 ||
   !Number.isInteger(obj.stock)||obj.stock<0 ||
   (obj.presentacion_ml!==null&&(!Number.isInteger(obj.presentacion_ml)||obj.presentacion_ml<1||obj.presentacion_ml>1000)))
    throw Error('Precios, stock o cantidad mínima inválidos. El precio al mayor no puede superar el precio al detal.');
  const status=form.querySelector('#admin-save-status');
  if(status){status.textContent='Enviando cambios a Supabase…';status.className='admin-save-status pending'}
  const file=fd.get('foto');if(file?.size)obj.imagen_url=await db.savePhoto(file,obj.id||obj.sku);
  const saved=await db.saveProduct(obj);
  if(page==='admin'&&activeAdminTab==='productos'&&location.protocol.startsWith('http')){history.replaceState(null,'',`admin.html?tab=productos&edit=${encodeURIComponent(saved.id)}`);}
  // Mantener lo recién guardado inmediatamente visible en la tabla, incluso si falla una consulta adicional.
  const existing=catalog.findIndex(p=>p.id===saved.id);
  if(existing>=0)catalog[existing]={...catalog[existing],...saved};else catalog.unshift(saved);
  renderAdminProductTable();
  const syncStatus=$('#admin-catalog-sync-status');
  if(syncStatus){syncStatus.classList.add('confirmed');syncStatus.innerHTML='<span class="sync-dot"></span> Producto '+safe(saved.sku)+' guardado en Supabase. Los clientes verán los nuevos valores en el catálogo al recargar.'}
  const editor=$('#admin-product-editor');
  if(editor){editor.innerHTML=productForm(saved);const confirmed=editor.querySelector('#admin-save-status');if(confirmed){confirmed.className='admin-save-status confirmed';confirmed.textContent='✓ Guardado en Supabase y comprobado por una segunda lectura: '+saved.sku+' · '+new Date().toLocaleTimeString('es-CO',{hour:'2-digit',minute:'2-digit'})+'.'+' Precio al detal: '+money(retail(saved))+' · Precio al mayor: '+money(wholesale(saved))+'.'}}
  toast('Producto guardado y confirmado en Supabase.');
  // No volver a dibujar el formulario durante la recarga para conservar la confirmación.
  db.getProducts({admin:true}).then(rows=>{catalog=rows;renderAdminProductTable()}).catch(e=>console.warn('Error al refrescar inventario tras guardar:',e));
  break;
 }
 case 'csv-import-form':{const file=fd.get('archivo');if(!file?.size)throw Error('Selecciona un Excel o CSV.');const rows=await parsePriceFile(file),existing=await db.getProducts({admin:true});if(!rows.length)throw Error('El CSV no tiene datos.');if(rows.length>2000)throw Error('Límite de 2.000 filas por archivo.');const parsed=rows.map(parseProductCSV),skus=new Set(),bySku=new Map(existing.map(p=>[p.sku,p]));for(const p of parsed){if(skus.has(p.sku))throw Error('SKU repetido: '+p.sku);skus.add(p.sku);if(!bySku.has(p.sku)&&!p.nombre)throw Error('Falta nombre para producto nuevo: '+p.sku)}if(!confirm(`Se actualizarán ${parsed.length} referencias según los campos completos del CSV. Los campos vacíos se conservarán. ¿Continuar?`))return;const progress=$('#csv-import-progress');const defaults={marca:'Sin especificar',genero:'Sin especificar',familia:'Otros',precio:null,precio_detal:null,precio_mayor:null,minimo_mayor:6,stock:0,notas:'',descripcion:'',ocasion:'Sin especificar',clima:'TODOS',presentacion_ml:null,concentracion:'Sin especificar',imagen_url:'',activo:true,destacado:false};const data=parsed.map(p=>({...defaults,...bySku.get(p.sku),...p}));await db.importProducts(data,done=>{if(progress)progress.textContent=`Guardando... ${done} de ${data.length} referencias`});catalog=await db.getProducts({admin:true});adminPageNumber=1;renderAdminProductTable();form.reset();if(progress)progress.textContent=`Listo: ${data.length} referencias sincronizadas con Supabase.`;toast(`${data.length} productos actualizados correctamente.`);break}
 case 'admin-order-form':{let id=get('id'),items=Array.from(form.querySelectorAll('[data-order-product]')).filter(x=>!x.disabled).map(x=>({product_id:x.dataset.orderProduct,cantidad:Number(x.value)}));if(items.some(x=>!Number.isInteger(x.cantidad)||x.cantidad<1||x.cantidad>20))throw Error('Cada cantidad debe estar entre 1 y 20.');await db.updateOrder({id,estado:get('estado')||null,nota:get('nota'),items});toast('Pedido actualizado.');root.innerHTML=header()+await admin()+footer();await openOrderEditor(id);break}
 }}
async function boot(){if(db.LIVE&&!db.client)throw Error('No se pudo inicializar Supabase. Revisa el script del CDN.');await db.refresh();catalog=await db.getProducts({admin:page==='admin'});favIds=await db.favorites();let content='';switch(page){case 'inicio':content=await home();break;case 'tienda':content=await shop();break;case 'producto':content=await detail();break;case 'carrito':content=await cart();break;case 'checkout':content=await checkout();break;case 'test':content=test();break;case 'favoritos':content=await favoritePage();break;case 'login':case 'registro':case 'recuperar':content=loginPage(page);break;case 'cuenta':content=await account();break;case 'pedidos':content=await orders();break;case 'pedido':content=await orderDetail();break;case 'admin':content=await admin();break;case 'nosotros':content=about();break;default:content=await home()}
 root.innerHTML=header()+`<main id="main-content">${content}</main>`+footer();updateCounters();if(page==='admin'&&db.profile?.rol==='ADMIN'&&activeAdminTab==='productos'){renderAdminProductTable(); const requested=new URLSearchParams(location.search).get('edit'); const selected=catalog.find(p=>p.id===requested); if(selected){const editor=$('#admin-product-editor');if(editor)editor.innerHTML=productForm(selected)}}if(page==='tienda'){const q=new URLSearchParams(location.search).get('q');if(q){$('#filter-search').value=q;filterProducts(true)}else filterProducts(true)}
 }
document.addEventListener('click',async e=>{if(e.target.closest('#nav-toggle')){const nav=$('#main-nav'),open=!nav.classList.contains('open');nav.classList.toggle('open',open);$('#nav-toggle').setAttribute('aria-expanded',String(open));return}const btn=e.target.closest('[data-action]');if(!btn)return;e.preventDefault();if(btn.disabled)return;btn.disabled=true;try{await action(btn)}catch(err){console.error(err);toast(err.message||'No se pudo completar la acción.','error')}finally{if(btn.isConnected)btn.disabled=false}});
document.addEventListener('input',e=>{if(['filter-search','filter-family','filter-gender','filter-sort'].includes(e.target.id)){filterProducts(true)}if(e.target.id==='admin-product-search'){adminSearch=e.target.value;adminPageNumber=1;renderAdminProductTable()}});
document.addEventListener('change',e=>{if(['filter-family','filter-gender','filter-sort'].includes(e.target.id))filterProducts(true);if(e.target.id==='admin-status-filter'){adminView=e.target.value;adminPageNumber=1;renderAdminProductTable()}if(e.target.id==='admin-order-filter'){let v=e.target.value;document.querySelectorAll('#admin-orders-table tr[data-order-status]').forEach(tr=>tr.hidden=Boolean(v&&tr.dataset.orderStatus!==v))}});
document.addEventListener('invalid',e=>{const field=e.target,form=field.closest?.('#admin-product-form');if(!form)return;const status=form.querySelector('#admin-save-status');if(status){status.className='admin-save-status failed';status.textContent='No se envió el formulario: revisa «'+(field.name||'campo')+'». '+(field.validationMessage||'Hay un dato inválido.')}} ,true);
document.addEventListener('submit',async e=>{if(!e.target.getAttribute('id')||!['login-form','register-form','reset-form','password-form','quiz-form','checkout-form','admin-product-form','csv-import-form','admin-order-form'].includes(e.target.getAttribute('id')))return;e.preventDefault();const form=e.target,button=form.querySelector('[type="submit"]');if(form.dataset.saving==='1')return;form.dataset.saving='1';if(button){button.disabled=true;button.setAttribute('aria-busy','true')}try{await submit(form)}catch(err){console.error('Error guardando formulario:',err);const status=form.querySelector('#admin-save-status');if(status){status.className='admin-save-status failed';status.textContent='No se confirmó el guardado: '+(err.message||'Error desconocido')+' · Revisa el campo indicado y vuelve a intentar.'}const progress=form.querySelector('#csv-import-progress');if(progress)progress.textContent='No se completó la importación: '+(err.message||'Error desconocido');toast(err.message||'No se pudo continuar.','error')}finally{form.dataset.saving='0';if(button?.isConnected){button.disabled=false;button.removeAttribute('aria-busy')}}});
boot().catch(err=>{console.error(err);root.innerHTML=`<div class="fatal-error"><div class="brand-symbol">K✦</div><h1>No se pudo abrir KingSeduccion</h1><p>${safe(err.message)}</p><p>${db.LIVE?'Revisa las credenciales públicas, las tablas SQL y la conexión a internet.':'Verifica que hayas abierto los archivos de la carpeta completa.'}</p><a href="index.html" class="btn btn-gold">Reintentar</a></div>`});
// Al volver a la tienda desde otra pestaña, consultar la base real (no una copia antigua).
let lastCatalogSync=Date.now();
async function syncPublicCatalog(){
 if(page==='admin'||!db.LIVE||Date.now()-lastCatalogSync<3500)return;
 try{
  const latest=await db.getProducts();lastCatalogSync=Date.now();
  if(!latest.length&&catalog.length)return;
  const previous=JSON.stringify(catalog.map(p=>[p.id,p.precio_detal,p.precio_mayor,p.stock,p.imagen_url,p.nombre,p.activo,p.destacado]));
  const next=JSON.stringify(latest.map(p=>[p.id,p.precio_detal,p.precio_mayor,p.stock,p.imagen_url,p.nombre,p.activo,p.destacado]));
  if(previous===next)return;
  catalog=latest;
  if(page==='tienda')filterProducts();
  else if(['inicio','producto','carrito','favoritos'].includes(page)){location.reload()}
 }catch(e){console.warn('No se pudo sincronizar el catálogo:',e)}
}
window.addEventListener('pageshow',e=>{if(e.persisted)syncPublicCatalog()});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)syncPublicCatalog()});
window.addEventListener('focus',syncPublicCatalog);
if('serviceWorker' in navigator&&location.protocol==='https:')navigator.serviceWorker.register('service-worker.js').catch(()=>{});
})();
